import './style.css';
import {Game,BIOMES} from './game.js';
import {HEROES,MONSTERS,branchEffect,VERSION} from './roster.js';
import {ACTIVE_SKILLS,ARMORY,ARMORY_COSTS,MASTERY_COSTS,RELICS,RITES,ASCENSIONS} from './content.js';
import {Scene} from './scene.js';
import {Input} from './input.js';
import {readProgress,saveProgress,buyArmory,buyMastery} from './progress.js';
import {api,metric,ads} from './services.js';
import {AudioSys} from '../core/AudioSynth.js';

class DamageTextPool{
 constructor(container){this.container=container;this.pool=[];this.active=[];}
 get(){const el=this.pool.pop()||document.createElement('div');el.className='dmg-num';el.style.cssText='position:absolute;pointer-events:none;font:bold 14px/1 "system-ui",sans-serif;text-shadow:0 1px 3px #000;transition:none;z-index:80;';this.active.push(el);this.container.appendChild(el);return el;}
 spawn(x,y,amount,crit){const el=this.get();el.textContent=crit?`${Math.round(amount)}!`:Math.round(amount);el.style.color=crit?'#f5c842':'#e8dfc8';el.style.fontSize=crit?'18px':'13px';el.style.left=`${x}px`;el.style.top=`${y}px`;el.style.opacity='1';el._age=0;el._life=crit?.9:.65;el._startY=y;}
 spawnGold(x,y,value){const el=this.get();el.textContent=`+${value} GOLD`;el.style.color='#facc15';el.style.fontSize='14px';el.style.left=`${x}px`;el.style.top=`${y}px`;el.style.opacity='1';el._age=0;el._life=.8;el._startY=y;}
 update(dt){for(let i=this.active.length-1;i>=0;i--){const el=this.active[i];el._age+=dt;const t=el._age/el._life;el.style.top=`${el._startY-t*36}px`;el.style.opacity=`${1-Math.pow(t,1.5)}`;if(el._age>=el._life){el.remove();this.pool.push(el);this.active.splice(i,1);}}}
 clear(){for(const el of this.active){el.remove();this.pool.push(el);}this.active=[];}
}

const $=id=>document.getElementById(id),progress=readProgress();
let game,scene,hero=HEROES[progress.selected]?progress.selected:'cinder',runToken=null,settled=false,lastFocus,toastTimer,dmgPool=null;
function save(){if(!saveProgress(progress))toast('Progress cannot be saved on this device.');}
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3500);}
function on(id,fn){$(id)?.addEventListener('click',fn);}
function modal(title,html){lastFocus=document.activeElement;$('modal-title').textContent=title;$('modal-body').innerHTML=html;$('modal').hidden=false;$('modal-body').querySelector('button')?.focus();}
function close(){$('modal').hidden=true;lastFocus?.focus?.();}
function initials(name){return name.split(' ').map(word=>word[0]).join('');}
function updateMenu(){$('banked-gold').textContent=`${progress.gold.toLocaleString()} gold`;$('records').hidden=progress.runs===0;$('records').textContent=progress.bestAscension?`Chronicle · Ascension ${progress.bestAscension}`:'Expedition chronicle & challenges';}
function applyAudio(){AudioSys.init();AudioSys.setMix({...progress.audio,master:progress.muted?0:progress.audio.master});}
function select(id){hero=id;progress.selected=id;const h=HEROES[id];$('selected-name').textContent=h.name;$('portrait-caption').textContent=`LIVE 3D MODEL / ${h.name} / ${h.weapon}`;document.documentElement.style.setProperty('--selected-hero',h.color);save();updateMenu();}
select(hero);
try{scene=new Scene($('world'));const hudEl=$('hud');dmgPool=hudEl?new DamageTextPool(hudEl):null;}catch(e){$('start').disabled=true;toast('WebGL is unavailable. Enable hardware acceleration.');console.error(e);}

function heroes(){modal('Eight souls. Eight oaths.',`<p class="muted">Select a hero to place their live 3D model in the cathedral showcase. Complete expeditions to awaken the remaining oaths.</p><div class="hero-grid">${Object.values(HEROES).map(h=>`<button class="hero-card ${h.id===hero?'selected':''}" data-hero="${h.id}" style="--hero-color:${h.color}" ${progress.runs<h.unlockRuns?'disabled':''}><div class="model-crest"><span>${initials(h.name)}</span></div><h3>${h.name}</h3><p>${h.trait}</p><small>${progress.runs<h.unlockRuns?`Complete ${h.unlockRuns} expeditions (${progress.runs}/${h.unlockRuns})`:h.weapon}</small></button>`).join('')}</div><button id="back">Return</button>`);document.querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>{select(b.dataset.hero);close();});on('back',close);}
on('heroes',heroes);

function armory(){const mastery=progress.mastery[hero]||0;modal('The Ember Armory',`<div class="armory-head"><p>Recovered gold strengthens every unranked descent. Ranked challenges ignore these bonuses.</p><strong>${progress.gold.toLocaleString()} GOLD</strong></div><h3>Shared forge</h3><div class="armory-grid">${Object.entries(ARMORY).map(([id,item])=>{const rank=progress.armory[id]||0,cost=ARMORY_COSTS[rank];return `<button class="armory-card" data-armory="${id}" ${rank>=item.max||progress.gold<cost?'disabled':''}><small>RANK ${rank} / ${item.max}</small><h3>${item.name}</h3><p>${item.desc}</p><span>${rank>=item.max?'MASTERED':`${cost} gold`}</span></button>`;}).join('')}</div><h3>${HEROES[hero].name} mastery</h3><div class="mastery-card"><p>${mastery===0?'+4% weapon damage':mastery===1?'-5% active-skill cooldown':mastery===2?'+10 starting signature charge and mastery aura':'All mastery oaths fulfilled.'}</p><button id="mastery-buy" ${mastery>=3||progress.gold<MASTERY_COSTS[mastery]?'disabled':''}>${mastery>=3?'Mastered':`Awaken rank ${mastery+1} · ${MASTERY_COSTS[mastery]} gold`}</button></div><button id="back">Return</button>`);document.querySelectorAll('[data-armory]').forEach(b=>b.onclick=()=>{if(buyArmory(progress,b.dataset.armory)){save();armory();}});on('mastery-buy',()=>{if(buyMastery(progress,hero)){save();armory();}});on('back',()=>{updateMenu();close();});}
on('armory',armory);

function settings(returnToPause=false){const slider=(id,label)=>`<label class="volume-setting"><span>${label}</span><input type="range" id="${id}" min="0" max="1" step=".05" value="${progress.audio[id]}"><output>${Math.round(progress.audio[id]*100)}</output></label>`;modal('Sound & accessibility',`<div class="settings-grid"><div><h3>Original procedural audio</h3><p class="muted">Music and effects are generated live in your browser. No recordings or copyrighted samples are used.</p>${slider('master','Master')}${slider('music','Music')}${slider('sfx','Combat effects')}${slider('ambience','Cathedral ambience')}<label class="setting"><input type="checkbox" id="sound" ${progress.muted?'':'checked'}> Audio enabled</label><label class="setting"><input type="checkbox" id="spatial" ${progress.spatialAudio?'checked':''}> Spatial audio</label></div><div><h3>Display & controls</h3><label class="setting"><input type="checkbox" id="motion" ${progress.reduced?'checked':''}> Reduce motion</label><label class="setting"><input type="checkbox" id="dmg-num" ${progress.damageNumbers?'checked':''}> Floating damage numbers</label><label class="volume-setting"><span>Screen-shake</span><input type="range" id="shake" min="0" max="2" step=".05" value="${progress.screenShake??1}"><output>${Math.round((progress.screenShake??1)*100)}%</output></label><p class="muted">WASD / arrows or Gamepad: move<br>Q / E (X / Y): smart-target skills · R (B): signature<br>Space (A): dodge · B / LB: build · Escape / Start: pause</p><button id="fullscreen">Fullscreen</button></div></div><button id="back">Return</button>`);for(const id of ['master','music','sfx','ambience'])$(id).oninput=e=>{progress.audio[id]=Number(e.target.value);e.target.nextElementSibling.value=Math.round(progress.audio[id]*100);applyAudio();save();};$('sound').onchange=e=>{progress.muted=!e.target.checked;applyAudio();save();};$('spatial').onchange=e=>{progress.spatialAudio=e.target.checked;save();};$('motion').onchange=e=>{progress.reduced=e.target.checked;save();};$('dmg-num').onchange=e=>{progress.damageNumbers=e.target.checked;save();};$('shake').oninput=e=>{progress.screenShake=Number(e.target.value);e.target.nextElementSibling.value=Math.round(progress.screenShake*100)+'%';save();};on('fullscreen',()=>document.documentElement.requestFullscreen?.().catch(()=>toast('Fullscreen unavailable.')));on('back',()=>{if(returnToPause&&game?.state==='paused'){game.state='playing';pause();}else close();});}
on('settings',()=>settings());

async function start(kind='solo'){if(!scene)return;$('start').disabled=true;try{let challenge;if(kind!=='solo'){challenge=await api('start',{kind});if(challenge.version!==VERSION)throw new Error('Challenge version is unavailable.');}runToken=challenge?.token||null;game=new Game({hero:challenge?.hero||hero,seed:challenge?.seed??crypto.getRandomValues(new Uint32Array(1))[0],ranked:!!challenge,modifier:challenge?.modifier,meta:progress});settled=false;close();$('menu').hidden=true;$('hud').hidden=false;hud();document.body.classList.add('playing');applyAudio();AudioSys.setScene('exploration');metric('run_start');}catch(e){toast(e.message);}finally{$('start').disabled=false;}}
on('start',()=>start());
function settle(){if(!game||settled)return;settled=true;if(['dead','victory'].includes(game.state)||game.time>=60)progress.runs++;if(game.state==='victory')progress.victories++;progress.bestAscension=Math.max(progress.bestAscension||0,game.ascension||0);progress.gold+=game.gold;progress.totalKills+=game.kills;progress.bossKills+=game.bossKills;progress.records.push({version:VERSION,hero:game.hero,duration:Math.floor(game.time),kills:game.kills,gold:game.earned,score:game.score(),victory:game.state==='victory',ascension:game.ascension||0});progress.records.sort((a,b)=>b.score-a.score);progress.records=progress.records.slice(0,10);save();}
function menu(){settle();game=null;close();$('menu').hidden=false;$('hud').hidden=true;document.body.classList.remove('playing');updateMenu();if(AudioSys.ctx)AudioSys.setScene('menu');}
function resume(){close();game.state='playing';AudioSys.setScene(game.enemies.some(e=>e.boss)?'boss':'exploration');}
function confirmQuit(){modal('Abandon this expedition?',`<p>Your recovered run gold will be banked, but this descent will end.</p><div class="row"><button id="cancel" class="primary">Continue fighting</button><button id="confirm-quit" class="danger">Abandon expedition</button></div>`);on('cancel',()=>{game.state='playing';pause();});on('confirm-quit',menu);}
function pause(){if(!game||game.state!=='playing')return;game.state='paused';AudioSys.setScene('menu');const p=game.player,modifier=ASCENSIONS[game.ascensionModifier];modal('Expedition paused',`<div class="pause-layout"><div class="pause-hero"><small>${BIOMES[game.biome].name}${game.ascension?` · ASCENSION ${game.ascension}`:''}</small><h3>${HEROES[game.hero].name}</h3><p>${modifier?`${modifier.name} — ${modifier.desc}`:HEROES[game.hero].weapon}</p><div class="pause-stats"><strong>${formatTime(game.time)}<span>TIME</span></strong><strong>${game.kills}<span>SLAIN</span></strong><strong>${Math.ceil(p.hp)} / ${p.maxHp}<span>VITALITY</span></strong><strong>${game.gold}<span>GOLD</span></strong></div></div><div class="pause-actions"><button id="resume" class="primary">Resume expedition <span>ESC</span></button><button id="build">Inspect build</button><button id="pause-settings">Sound & accessibility</button><button id="quit" class="danger">Return to camp</button></div></div>`);on('resume',resume);on('build',build);on('pause-settings',()=>settings(true));on('quit',confirmQuit);}
function build(){if(!game||!['playing','paused'].includes(game.state))return;game.state='paused';const h=HEROES[game.hero],skills=ACTIVE_SKILLS[game.hero],relics=Object.keys(game.player.relics),rites=Object.entries(game.player.rites).filter(([,rank])=>rank),p=game.player;const shopItems=game.merchantOffers&&game.merchantOffers.length?game.merchantOffers:game.merchantPool().slice(0,3);const canHeal=game.gold>=15&&p.hp<p.maxHp;modal(`${h.name} / Build & Reliquary Shop`,`<div class="merchant-head"><p>${h.weapon} · ${h.trait}</p><strong>${game.gold} RUN GOLD</strong></div><div class="skill-summary">${skills.map((s,i)=>`<div><small>${i?'E':'Q'} ACTIVE</small><strong>${s.name}</strong><span>${s.desc}</span></div>`).join('')}</div><div class="cards">${h.branches.map((name,i)=>`<div class="card"><small>BRANCH ${i+1} / ${p.ranks[i]} OF 3</small><h3>${name}</h3><p>${branchEffect(h.id,i,p.ranks[i])}</p><div class="ranks">${[1,2,3].map(n=>`<span class="${p.ranks[i]>=n?'lit':''}">${n}</span>`).join(' → ')}</div></div>`).join('')}</div><div class="merchant-head" style="margin-top:12px"><h4>Reliquary Blessings</h4><span>Spend run gold to power your expedition</span></div><div class="cards">${shopItems.map(id=>{const item=RELICS[id]||RITES[id],cost=game.merchantCost(id),owned=p.relics[id]||p.rites[id];return `<button class="card merchant-card" data-shop="${id}" ${game.gold<cost||(p.relics[id]&&!RITES[id])?'disabled':''}><small>${cost} GOLD${owned?` · BOUND`:''}</small><h3>${item?.name||id}</h3><p>${item?.desc||''}</p><span>${RITES[id]?'Repeatable Rite':'Run Relic'}</span></button>`;}).join('')}<button class="card merchant-card" id="altar-heal" ${!canHeal?'disabled':''}><small>15 GOLD</small><h3>Vessel Mend</h3><p>Restore 35 Vitality and gain 25 Ward shield immediately.</p><span>Altar Infusion</span></button></div><p class="muted">Relics: ${relics.length?relics.map(id=>RELICS[id]?.name).join(' · '):'None yet'}${rites.length?`<br>Rites: ${rites.map(([id,rank])=>`${RITES[id].name} ${rank}`).join(' · ')}`:''}</p><div class="row"><button id="resume" class="primary">Return to battle</button></div>`);document.querySelectorAll('[data-shop]').forEach(b=>b.onclick=()=>{const id=b.dataset.shop,cost=game.merchantCost(id),item=RELICS[id]||RITES[id];if(game.gold>=cost&&item){game.gold-=cost;game.spent+=cost;game.applyRelic(id);AudioSys.play('uiClick');toast(`${item.name} bound to your ember!`);build();}});on('altar-heal',()=>{if(game.gold>=15&&p.hp<p.maxHp){game.gold-=15;game.spent+=15;p.hp=Math.min(p.maxHp,p.hp+35);p.shield+=25;AudioSys.play('pickup',{kind:'potion'});toast('Vessel mended: +35 Vitality, +25 Ward!');build();}});on('resume',resume);}
function level(){modal(`Level ${game.player.level} / Choose your path`,`<p class="muted">Each branch has three ranks. The third transforms its effect.</p><div class="cards">${game.choices.map((c,i)=>`<button class="card upgrade" data-choice="${c.id}"><small>${i+1} / RANK ${c.rank+1} OF ${c.max}</small><h3>${c.name}</h3><p>${c.desc}</p><span>${c.connection}</span></button>`).join('')}</div>`);document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(game.upgrade(b.dataset.choice))close();});}
function merchant(){const offers=game.merchantOffers;modal('The Reliquary Merchant',`<div class="merchant-head"><p>Bind one relic or repeatable rite before the next sanctuary.</p><strong>${game.gold} RUN GOLD</strong></div><div class="cards">${offers.map(id=>{const r=RELICS[id]||RITES[id],cost=game.merchantCost(id),rank=game.player.rites[id]||0;return `<button class="card merchant-card" data-relic="${id}" ${game.gold<cost?'disabled':''}><small>${cost} GOLD${rank?` · RANK ${rank+1}`:''}</small><h3>${r.name}</h3><p>${r.desc}</p><span>${RITES[id]?'Repeatable endless rite':'Run relic · lost after the expedition'}</span></button>`;}).join('')}</div><div class="row"><button id="reroll" ${game.merchantRerolled||game.gold<5?'disabled':''}>Reroll · 5 gold</button><button id="skip">Continue without a binding</button></div>`);document.querySelectorAll('[data-relic]').forEach(b=>b.onclick=()=>{const item=RELICS[b.dataset.relic]||RITES[b.dataset.relic];if(game.buyMerchant(b.dataset.relic)){close();toast(`${item.name} bound to your ember.`);}});on('reroll',()=>{if(game.rerollMerchant())merchant();});on('skip',()=>{game.skipMerchant();close();});}
function convergence(){modal(game.cycle?'The cycle is broken again':'The three guardians have fallen',`<p>You may bank this victory now, or carry the same build into an endless ascension. Each cycle mixes enemy regions, rotates a dangerous modifier, strengthens guardians, and unlocks repeatable blessings.</p><div class="statline"><strong>${formatTime(game.time)}<small>SURVIVED</small></strong><strong>${game.kills}<small>SLAIN</small></strong><strong>${game.cycle}<small>ASCENSIONS</small></strong></div><div class="row"><button id="claim" class="primary">Claim victory</button><button id="endless">Enter ascension ${game.cycle+1}</button></div>`);on('claim',()=>game.claimVictory());on('endless',()=>{close();game.continueEndless();});}
async function finish(victory){settle();const duration=Math.floor(game.time),token=runToken;runToken=null;metric('run_complete');const goldBox=`<div class="death-gold-box" style="background:rgba(212,175,55,0.12);border:1px solid #d4af37;border-radius:4px;padding:12px;margin:12px 0;text-align:center;"><strong style="color:#ffd700;font-size:15px;font-family:'Cinzel',serif;display:block;">+${game.gold} GOLD BANKED FOR UPGRADES</strong><p style="margin:4px 0 0;font-size:11px;color:#d5d3ba;">Camp Treasury: <strong>${progress.gold.toLocaleString()} gold</strong> available for permanent upgrades.</p></div>`;modal(victory?'The last light endures':'The Ember Diminishes',`<p>${victory?game.ascension?`The ember returned from ascension ${game.ascension}. Your record is sealed.`:'Three guardians have fallen. The sanctuaries are silent.':'The horde overwhelmed your vessel. Your recovered gold is safe in camp.'}</p><div class="statline"><strong>${formatTime(game.time)}<small>SURVIVED</small></strong><strong>${game.kills}<small>SLAIN</small></strong><strong>${game.score().toLocaleString()}<small>SCORE</small></strong></div>${!victory?goldBox:`<p class="muted">${game.earned} gold found · ${game.spent} spent · ${game.gold} recovered${game.ascension?` · ascension ${game.ascension}`:''}</p>`}<p id="upload-status"></p><div class="row">${!victory?'<button id="to-armory" class="primary">Upgrade in Armory ↗</button>':''}<button id="again" ${victory?'class="primary"':''}>Descend again</button><button id="return">Camp menu</button></div>${!game.ranked&&ads.available()?'<button id="reward">Watch an ad · recover 50 gold</button>':''}`);on('to-armory',()=>{close();armory();});on('again',()=>start());on('return',menu);let rewardPending=false;on('reward',async()=>{if(rewardPending)return;rewardPending=true;$('reward').disabled=true;if(await ads.reward()){progress.gold+=50;save();$('reward').textContent='50 gold recovered';}else{rewardPending=false;$('reward').disabled=false;}});if(token){const target=$('upload-status');try{await api('submit',{token,duration,kills:game.kills,gold:game.earned,victory});target.textContent='Challenge recorded.';}catch(e){target.textContent=`Score not submitted: ${e.message}`;}}if(!game?.ranked)ads.interstitial(duration,victory);}
async function records(kind='local'){modal('The Ember Chronicle',`<div class="row"><button id="local">This device</button><button id="daily">Daily</button><button id="weekly">Weekly</button></div><p id="board-status"></p><div id="record-list"></div><button id="back">Return</button>`);on('back',close);on('local',()=>records());on('daily',()=>records('daily'));on('weekly',()=>records('weekly'));const target=$('record-list'),status=$('board-status');try{const rows=kind==='local'?progress.records:(await api(`board&kind=${kind}`)).records;if(kind==='local'){const milestones=[['First Light',progress.victories>=1,'Claim one victory'],['Deepwalker',progress.bestAscension>=1,'Reach ascension 1'],['Unbroken',progress.bestAscension>=3,'Reach ascension 3'],['Gravetide',progress.totalKills>=1000,'Slay 1,000 enemies'],['Guardian Bane',progress.bossKills>=25,'Defeat 25 guardians']];status.textContent=`${progress.runs} expeditions · ${progress.victories} victories · ascension ${progress.bestAscension||0} · ${progress.totalKills.toLocaleString()} slain`;const chronicle=document.createElement('div');chronicle.className='chronicle';for(const [name,done,desc] of milestones){const p=document.createElement('p');p.className=done?'complete':'';p.textContent=`${done?'SEALED':'UNLIT'} · ${name} — ${desc}`;chronicle.appendChild(p);}target.appendChild(chronicle);}else status.textContent='Same hero and seed for every challenger. Armory and endless ascensions are disabled.';for(const r of rows){const p=document.createElement('p');p.textContent=`${HEROES[r.hero]?.name||'Unknown'} · ${formatTime(r.duration)} · ${Number(r.score).toLocaleString()} points${r.ascension?` · ascension ${r.ascension}`:''}`;target.appendChild(p);}if(kind!=='local'){const b=document.createElement('button');b.textContent=`Play ${kind} challenge`;b.onclick=()=>start(kind);target.appendChild(b);}}catch(e){status.textContent=e.message;}}
on('records',()=>records());

let input;
function action(name,value){if(name==='fullscreen'){document.documentElement.requestFullscreen?.();return;}if(name==='toast'){toast(value);return;}if(!game)return;if(name==='pause'){if(game.state==='playing')pause();else if(game.state==='paused')resume();}if(name==='autopause')pause();if(name==='dash'){const v=input.vector();game.dash(v.x,v.z);}if(name==='skill')game.useSkill(value);if(name==='ultimate')game.ultimate();if(name==='shop')build();if(name==='choice'&&game.state==='upgrade'){const c=game.choices[value];if(c&&game.upgrade(c.id))close();}}
input=new Input(action);document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));
document.addEventListener('keydown',e=>{if(e.key!=='Tab'||$('modal').hidden)return;const els=[...$('modal').querySelectorAll('button:not(:disabled),input,select')],first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus?.();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus?.();}});
function formatTime(s){return `${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;}
